import numpy as np

def sigmoid(x):
    x = np.asarray(x, dtype=float)
    # Clipping avoids overflow for extremely large magnitudes.
    x = np.clip(x, -500, 500)
    return 1 / (1 + np.exp(-x))

def tanh(x):
    return np.tanh(x)

def relu(x):
    return np.maximum(0, x)

def leaky_relu(x, alpha=0.01):
    return np.where(x >= 0, x, alpha * x)

def softmax(logits):
    logits = np.asarray(logits, dtype=float)
    shifted = logits - np.max(logits, axis=-1, keepdims=True)
    exp_values = np.exp(shifted)
    return exp_values / np.sum(exp_values, axis=-1, keepdims=True)

values = np.array([-3.0, -1.0, 0.0, 1.0, 3.0])

print('Sigmoid:', sigmoid(values))
print('Tanh:', tanh(values))
print('ReLU:', relu(values))
print('Leaky ReLU:', leaky_relu(values))

logits = np.array([2.0, 1.0, 0.0])
probabilities = softmax(logits)
print('Softmax:', probabilities)
print('Probability sum:', probabilities.sum())
